// -- Server requests (server to client, answered) --
export interface ServerRequestMap {
  /** A tool call waits for the user's approval. */
  approval: { params: ApprovalParams; result: ApprovalResult }
  /** The agent asks the user 1 to 5 questions (the ask_user tool). */
  ask_user: { params: AskParams; result: AskResult }
  /** An outside executor asks to use one of its tools; it waits, with no deadline, until the user answers or it is stopped. */
  'executor.approval': { params: ExecutorApprovalParams; result: ExecutorApprovalResult }
  /** An outside executor asks the user questions; it waits, with no deadline. */
  'executor.question': { params: ExecutorQuestionParams; result: ExecutorQuestionResult }
  /** The agent asks the user for an API key by name (the secrets tool). The card is masked; the value goes straight to the vault and is never sent back. */
  secret: { params: SecretParams; result: SecretResult }
}
export type ServerRequestMethod = keyof ServerRequestMap
export const SERVER_REQUEST_METHODS = [
  'approval',
  'ask_user',
  'executor.approval',
  'executor.question',
  'secret'
] as const satisfies readonly ServerRequestMethod[]

// -- Events (server to client, `event` notifications) --
export interface EventMap {
  /** A bot was made, changed or deleted; read bot.list. */
  'bots.changed': BotsChanged
  /** A background command of the conversation started or ended. */
  'command.update': CommandRow
  /** A channel made a conversation, or a turn in one began or ended; read conversation.list. */
  'conversations.changed': ConversationsChanged
  /** An executor's accounts, or the account of one of its folders, changed; read executor.accounts and executor.folders. */
  'executor.accounts': AccountsChanged
  /** An executor's plan usage changed: read with executor.usage, or told by its harness as one of its instances worked. */
  'executor.usage': ExecutorUsageRow
  /** An item was installed, updated, removed or retired, from any client or the terminal; read marketplace.list. */
  'marketplace.changed': MarketplaceChanged
  /** The turn ended: its text and outcome. */
  'message.complete': MessageComplete
  /** A piece of the reply's text. */
  'message.delta': Said
  /** A plugin's tool sent the user a file (SDK version 22, the voice plugin's spoken answer), kept in the home's attachments: shown in the turn, and sent in a channel's chat. */
  'message.file': AttachmentRow
  /** The text streamed since the last model call was interim: the call asked for tools. Said before its first tool.start. */
  'message.interim': Interim
  /** A turn began with what the user said. */
  'message.start': UserSaid
  /** A message sent mid-turn entered the turn. */
  'message.steered': UserSaid
  /** A plugin was turned on, off or failed, or someone asked to pair; read plugin.list and pairing.list. */
  'plugins.changed': PluginsChanged
  /** The agent closes a preview tab of the conversation, or all of them. */
  'preview.close': PreviewPayload
  /** The agent asks to show something beside the conversation, in a tab of the app's side panel; never taking the focus from another conversation. */
  'preview.open': PreviewPayload
  /** A memory proposal was made, approved or discarded; read them with memory.proposals. */
  'proposals.changed': ProposalCount
  /** A piece of the model's readable reasoning. */
  'reasoning.delta': Said
  /** An open server request was withdrawn; take its card down. */
  'request.cancel': RequestCancel
  /** The background review changed something. */
  'review.summary': ReviewSummary
  /** A routine's run ended; notify, unless its status is silent. */
  'routine.finished': RoutineFinished
  /** A routine was made, changed, paused, resumed, removed or ran; read routine.list. */
  'routines.changed': RoutinesChanged
  /** The first frame of a connection: the version, and the epoch of event numbers. */
  'server.ready': Ready
  /** Something happened to the conversation. */
  'status.update': StatusUpdate
  /** A subagent of the conversation started, ran a tool or ended. */
  'subagent.update': SubagentRow
  /** One of this client's terminals ended: its shell exited. */
  'terminal.exit': TerminalExit
  /** What one of this client's terminals wrote; only the client that opened it gets it. */
  'terminal.output': TerminalOutput
  /** A model titled the conversation; its row in the list takes the new title. */
  'title.changed': TitleChanged
  /** A tool call finished. */
  'tool.complete': ToolComplete
  /** What a running tool reported. */
  'tool.progress': ToolProgressPayload
  /** A tool call began. */
  'tool.start': ToolStart
  /** The update of the server's host ended, in the minutes before this connection: the server that restarted tells each client as it connects. */
  'update.ended': UpdateEnded
  /** An executor instance said, thought, called, got or was given something. */
  'workbench.activity': InstanceActivityPayload
  /** An executor instance on the workbench started, changed or ended; the workbench is the same in every conversation. */
  'workbench.update': InstanceRow
}
export type EventName = keyof EventMap
export const EVENT_NAMES = [
  'bots.changed',
  'command.update',
  'conversations.changed',
  'executor.accounts',
  'executor.usage',
  'marketplace.changed',
  'message.complete',
  'message.delta',
  'message.file',
  'message.interim',
  'message.start',
  'message.steered',
  'plugins.changed',
  'preview.close',
  'preview.open',
  'proposals.changed',
  'reasoning.delta',
  'request.cancel',
  'review.summary',
  'routine.finished',
  'routines.changed',
  'server.ready',
  'status.update',
  'subagent.update',
  'terminal.exit',
  'terminal.output',
  'title.changed',
  'tool.complete',
  'tool.progress',
  'tool.start',
  'update.ended',
  'workbench.activity',
  'workbench.update'
] as const satisfies readonly EventName[]
/** Events that belong to a conversation: they carry its id and their number. */
